  "GroupId":"@TGS#37AB3PAEC", // 群组 ID（必填）

  "AppDefinedDataFilter_GroupMember": [ // 群成员自定义字段过滤器

      "MemberDefined2" // 群成员自定义字段Key

  ]

}

